import { beforeEach, describe, expect, it } from 'vitest';

import { isGeneratedSource } from '../src/core/codemirror/code-index.js';
import type { Db } from '../src/db/client.js';
import { clearAssembleCache, assembleFor, buildIndex, type IndexDeps } from '../src/core/codemirror/index-store.js';
import type { MirrorResult } from '../src/core/codemirror/mirror.js';

/**
 * 生成代码不进索引（2026-11-09，接 79 个 Go 仓之前的那道门）。
 *
 * ── 为什么这是一次「必须做」的修复，不是优化
 *
 * `apisrv` 实测：583 个可索引文件里 231 个（39.6%）是 GoFrame 生成的 model / dao，
 * 每个文件头上一句 `// Code generated by gf gen dao. DO NOT EDIT.`。它们进 outline 之后，
 * 材料会把 `UserVip` 这种**数据库表的镜像**说成「产品已有的能力」——那不是漏信息，
 * 是一句假话。而假话比空白糟：空白会让人去查，假话不会。
 *
 * ── 这一组用例钉四件事
 *
 * 1. 头部的标准形状被认出来（包括 build tag 之后的那个位置）；
 * 2. 只是「正文里出现 DO NOT EDIT」不算生成代码（窗口是前 5 行，不扫全文）；
 * 3. **两条建索引的路都跳过它**：`buildIndex`（纯函数、不写库）与 `assembleFor`
 *    （生产读路径、写库 + join 已有内容）；
 * 4. 跳过的**数量**是可观察的（`skippedGenerated`），因为它要进覆盖率表——
 *    「静默变小」正是这次要消灭的东西。
 */

/** GoFrame 生成文件的头（实测形状，逐字）。 */
const GOFORM_HEADER = '// Code generated by gf gen dao. DO NOT EDIT.\n';

/** 一个非生成的业务文件：函数 `GetUserCustomDomainIsShortLink` 在服务层。 */
const HANDLER = [
  'package service',
  '',
  '// GetUserCustomDomainIsShortLink 判断某个域名是不是短链域名。',
  'func GetUserCustomDomainIsShortLink(domain string) bool {',
  '\treturn domain != ""',
  '}',
  '',
].join('\n');

/** 生成出来的 model：结构体是数据库表的镜像，不是产品能力。 */
const GENERATED_MODEL = [
  GOFORM_HEADER,
  '',
  'package model',
  '',
  'type UserVip struct {',
  '\tId   uint',
  '\tName string',
  '}',
  '',
].join('\n');

describe('isGeneratedSource：只认文件自己那一句话', () => {
  it('第一行就是标准头 → 生成代码', () => {
    expect(isGeneratedSource(GOFORM_HEADER)).toBe(true);
  });

  it('build tag 之后（Go 的常规位置）也认', () => {
    const text = [
      '//go:build linux',
      '',
      '// Code generated by protoc-gen-go. DO NOT EDIT.',
      'package api',
      '',
    ].join('\n');
    expect(isGeneratedSource(text)).toBe(true);
    // `/* … */` 形状同样是标准写法（protoc 老版本）。
    expect(isGeneratedSource('/* Code generated by tool. DO NOT EDIT. */\npackage x\n')).toBe(true);
  });

  it('正文里出现 DO NOT EDIT、但不是文件头 → **不是**生成代码', () => {
    // 窗口是前 5 行：第 6 行之后的任何字样都不该让一个手写文件消失。
    const text = [
      'package service',
      '',
      '// 注意：这个文件不要手改。',
      '// 它由同事在别处生成后贴过来，但我们把它当源码维护。',
      '',
      '// Code generated by hand. DO NOT EDIT.',
      'func A() {}',
    ].join('\n');
    expect(isGeneratedSource(text)).toBe(false);
  });

  it('缺了「Code generated」或「DO NOT EDIT.」的一半都不算', () => {
    expect(isGeneratedSource('// Code generated by tool\npackage x\n')).toBe(false);
    expect(isGeneratedSource('// DO NOT EDIT.\npackage x\n')).toBe(false);
    expect(isGeneratedSource(HANDLER)).toBe(false);
  });
});

// ─── 两条建索引的路 ──────────────────────────────────────────────────────────

/** 假树：三个 Go 文件，shas 是编的（不碰 ssh）。 */
const ENTRIES = [
  { path: 'service/cdn_link.go', oid: 'a'.repeat(40), size: HANDLER.length },
  { path: 'model/user_vip.go', oid: 'b'.repeat(40), size: GENERATED_MODEL.length },
  { path: 'service/cdn_link_test.go', oid: 'c'.repeat(40), size: 40 },
];

const CONTENTS = new Map<string, string>([
  ['a'.repeat(40), HANDLER],
  ['b'.repeat(40), GENERATED_MODEL],
  ['c'.repeat(40), 'package service\nfunc TestX(t *testing.T) {}\n'],
]);

/** 只做两件事的依赖：列树、按 blob id 读内容。一次 ssh 都不发。 */
const fakeDeps: IndexDeps = {
  lsTreeEntries: async () => ({ ok: true, data: ENTRIES }) as MirrorResult<typeof ENTRIES>,
  showHeads: async () => ({ ok: true, data: new Map() }) as MirrorResult<Map<string, string>>,
  readBlobs: async (_repo, refs) => {
    const out = new Map<string, string>();
    for (const ref of refs) {
      const text = CONTENTS.get(ref.blobSha);
      if (text !== undefined) out.set(ref.blobSha, text);
    }
    return { ok: true, data: out } as MirrorResult<Map<string, string>>;
  },
};

describe('buildIndex：生成的 model 文件不进索引，但数得出来', () => {
  it('`UserVip` 这个生成结构体不在 outline 里，`skippedGenerated` = 1', async () => {
    const built = await buildIndex('fixture-generated', 'f'.repeat(40), fakeDeps);
    expect(built.ok).toBe(true);
    if (!built.ok) return;
    const index = built.data.index;

    // 真产品代码在（而且它自己的 outline 正常）。
    expect(Object.keys(index.files).sort()).toEqual(['service/cdn_link.go']);
    expect(index.outline['service/cdn_link.go']).toEqual([
      { kind: 'go-func', name: 'GetUserCustomDomainIsShortLink', line: 4 },
    ]);
    // 生成的 model 一行都不该带进来。
    expect(index.files['model/user_vip.go']).toBeUndefined();
    expect(index.outline['model/user_vip.go']).toBeUndefined();
    // 跳过的数量是账，不是日志：覆盖率表靠它把「正当跳过」与「读不回来」分开。
    expect(index.skippedGenerated).toBe(1);
  });
});

/**
 * `assembleFor` 的最小库桩：**会记住写进去的行**（`blob_index` 的语义就是「只解析一次」）。
 *
 * 为什么值得写这十几行：`assembleFor` 是**生产读路径**（走查/评审懒建索引走它），
 * 而 `buildIndex` 只有 `--dry-run` 与纯函数用例用。两条路的跳过口径必须一致，
 * 两条都要有用例——而为了验一条 `continue` 去连一次 dogyun 是不划算的。
 */
function stubDb(): Db {
  const rows: Array<Record<string, unknown>> = [];
  return {
    select: () => ({ from: () => ({ where: async () => rows }) }),
    insert: () => ({
      values: (values: unknown[]) => ({
        onConflictDoNothing: () => ({
          returning: async () => {
            for (const value of values) {
              const row = value as Record<string, unknown>;
              rows.push({ ...row, parsedAt: '2026-11-09T00:00:00.000Z' });
            }
            return values.map((value) => ({ blobSha: (value as { blobSha: string }).blobSha }));
          },
        }),
      }),
    }),
  } as unknown as Db;
}

describe('assembleFor：生产读路径同一个口径', () => {
  beforeEach(() => {
    clearAssembleCache();
  });

  /**
   * 为什么这一条不能省：`assembleFor` 是**生产读路径**（走查 / 评审懒建索引都走它），
   * 而 `buildIndex` 只有 `--dry-run` 与纯函数用例用。跳过生成代码这件事，两条路必须一致——
   * 只修一条的后果是「用例全绿、材料照旧把 `UserVip` 当产品能力」，正是这次要消灭的形状。
   */
  it('生产读路径也跳过生成文件，且跳过数落在 index 上（不是只落在日志里）', async () => {
    const assembled = await assembleFor(stubDb(), 'fixture-generated', 'f'.repeat(40), fakeDeps);
    expect(assembled.ok).toBe(true);
    if (!assembled.ok) return;
    expect(Object.keys(assembled.data.index.files)).toEqual(['service/cdn_link.go']);
    expect(assembled.data.index.outline['model/user_vip.go']).toBeUndefined();
    expect(assembled.data.skippedGenerated).toBe(1);
    expect(assembled.data.index.skippedGenerated).toBe(1);
  });
});
